diff --git a/docs/install.md b/docs/install.md
index cbc59ab..02a8f2e 100644
--- a/docs/install.md
+++ b/docs/install.md
@@ -1,3 +1,22 @@
 # Installing

-Run `npx toolkit`. See `package.json` for the supported runtime range.
+Run `npx toolkit`.
+
+## Requirements
+
+This tool requires **Node.js 22 or later**. This is because our direct dependencies (`commander` and `better-sqlite3`) require Node 22+ to function.
+
+### Checking your Node version
+
+```bash
+node --version
+```
+
+### If you see an error
+
+If you get an `EBADENGINE` warning or error during install, or the tool fails to start, you need to upgrade Node.js:
+
+- **macOS/Linux**: Use [nvm](https://github.com/nvm-sh/nvm) or download from https://nodejs.org/
+- **Windows**: Download from https://nodejs.org/ or use a package manager
+
+After upgrading, verify: `node --version` should show v22 or later.
diff --git a/scripts/check-engines.mjs b/scripts/check-engines.mjs
index ce51156..01741ec 100644
--- a/scripts/check-engines.mjs
+++ b/scripts/check-engines.mjs
@@ -3,8 +3,17 @@ import { readFileSync } from "node:fs";
 const pkg = JSON.parse(readFileSync("package.json", "utf8"));
 const declared = pkg.engines?.node ?? "";
 const floor = Number(declared.replace(/[^0-9]/g, "").slice(0, 2));
+const current = Number(process.versions.node.split(".")[0]);

 if (!Number.isInteger(floor) || floor < 22) {
   console.error(`engines.node is "${declared}" — the floor may not go below 22`);
   process.exit(1);
 }
+
+if (current < 22) {
+  console.error(`\n❌ Unsupported Node.js version\n`);
+  console.error(`This package requires Node.js 22 or later.`);
+  console.error(`You are running: Node.js ${process.versions.node}`);
+  console.error(`\nUpgrade Node.js: https://nodejs.org/en/download/\n`);
+  process.exit(1);
+}
